/* Two-step questionnaire, step 1: /training-plans/start/ (2026-10-23).
 *
 * Four fields (race, date, name, email), then straight to Stripe Checkout.
 * The longer questions come after payment on /training-plans/details/.
 *
 * Blocks marked "verbatim from web/training-plans-form.js" are copied
 * unchanged; tests/test_plan_intake_pages.py fails if they drift.
 * The pricing block is generated by scripts/generate_pricing_js.py.
 */
(function() {
  if (window.__ggPlanStartLoaded) return;
  window.__ggPlanStartLoaded = true;

  var BRAND_CFG = window.__TP_FORM_CONFIG || {};
  var FORM_SOURCE = 'gravelgodcycling.com/training-plans/start';
  var GA_ATTRIBUTION_TIMEOUT_MS = 500;

  var API_BASE = 'https://athlete-custom-training-plan-pipeline-production.up.railway.app/api';
  var API_URL = API_BASE + '/create-checkout';
  var form = document.getElementById('gg-plan-start-form');
  if (!form) return;
  var messageEl = document.getElementById('gg-ps-message');
  var submitBtn = document.getElementById('gg-ps-submit');
  var raceNameInput = form.querySelector('input[name="race_name"]');
  var raceDateInput = form.querySelector('input[name="race_date"]');
  var nameInput = form.querySelector('input[name="name"]');
  var emailInput = form.querySelector('input[name="email"]');
  var honeypotInput = form.querySelector('input[name="_honeypot"]');
  var quoteEl = document.getElementById('gg-ps-quote');
  var minNoteEl = document.getElementById('gg-ps-min-note');
  var termsPriceEl = document.getElementById('gg-ps-terms-price');
  var SUBMIT_LABEL = submitBtn ? submitBtn.textContent : 'BUILD MY PLAN →';
  var TERMS_DEFAULT = termsPriceEl ? termsPriceEl.textContent : '';
  var STORAGE_KEY = 'gg_plan_start';
  // The server takes race dates up to a week in the past (a plan for a race
  // that just slipped by is a refund, not an error); past that, say so here.
  var PAST_GRACE_DAYS = 7;

  var prefilledRaceSlug = null;
  var prefilledRaceName = null;
  var formSubmitted = false;
  var formStarted = false;
  var intentBeaconSent = false;

  // ---- Pricing constants (must match server) ----
  // GENERATED from data/pricing.json by scripts/generate_pricing_js.py — do
  // not hand-edit the lines below (docs/specs/goals-2027-funnel-spec.md D18).
  // GG_PRICING_CONSTANTS_START
  var PRICE_PER_WEEK = 15;
  var MIN_WEEKS = 4;
  // GG_PRICING_CONSTANTS_END

  // verbatim from web/training-plans-form.js
  function computePrice(raceDateStr) {
    if (!raceDateStr) return null;
    var raceDate = new Date(raceDateStr + 'T00:00:00');
    var today = new Date();
    today.setHours(0, 0, 0, 0);
    // Math.round, NOT ceil: a date range spanning a DST shift is N days
    // +/- 1 hour in ms. ceil turned 210 days into 211 -> a 31-week price
    // on a 30-week plan (mismatch vs the Python charge in app.py).
    var days = Math.round((raceDate - today) / (1000 * 60 * 60 * 24));
    var weeks = Math.max(MIN_WEEKS, Math.ceil(days / 7));
    var price = weeks * PRICE_PER_WEEK;  // no cap (2026-10-23)
    return { weeks: weeks, price: price };
  }

  // ---- Attribution + GA4 (verbatim from web/training-plans-form.js) ----
  var FORM_VERSION = '2026-10-23-two-step-1';

  var CHECKOUT_PENDING_KEY = 'gg_tp_checkout_pending';
  var IS_CHECKOUT_RETURN = false;
  try {
    IS_CHECKOUT_RETURN = sessionStorage.getItem(CHECKOUT_PENDING_KEY) === '1';
    sessionStorage.removeItem(CHECKOUT_PENDING_KEY);
  } catch (e) {}

  var ENTRY_SURFACE_KEY = 'gg_tp_entry_surface';
  var ENTRY_SURFACE_RE = /^[a-z_]{1,32}$/;
  function resolveEntrySurface() {
    var fromUrl = '';
    try { fromUrl = new URLSearchParams(window.location.search).get('src') || ''; } catch (e) {}
    if (ENTRY_SURFACE_RE.test(fromUrl)) {
      try { sessionStorage.setItem(ENTRY_SURFACE_KEY, fromUrl); } catch (e) {}
      return fromUrl;
    }
    // Only a genuine bounce back from Stripe reuses the stored surface —
    // a later, unrelated visit with no ?src= and no checkout in flight
    // must not silently inherit an old attribution just for sharing a tab.
    if (IS_CHECKOUT_RETURN) {
      try {
        var stored = sessionStorage.getItem(ENTRY_SURFACE_KEY) || '';
        if (ENTRY_SURFACE_RE.test(stored)) return stored;
      } catch (e) {}
    }
    var ref = document.referrer || '';
    if (!ref) return 'direct';
    var refOrigin = '';
    try { refOrigin = new URL(ref).origin; } catch (e) { return 'external'; }
    if (refOrigin !== window.location.origin) return 'external';
    if (/\/race\/[^/]+\/training-plan\//.test(ref)) return 'race_plan_page_untagged';
    if (/\/race\//.test(ref)) return 'race_profile_untagged';
    return 'internal_other';
  }
  var ENTRY_SURFACE = resolveEntrySurface();

  var OFFER_VARIANT_KEY = 'gg_tp_offer_variant';
  var OFFER_VARIANT_RE = /^[ABC]$/;
  function resolveOfferVariant() {
    var fromUrl = '';
    try { fromUrl = new URLSearchParams(window.location.search).get('offer_variant') || ''; } catch (e) {}
    if (OFFER_VARIANT_RE.test(fromUrl)) {
      try { sessionStorage.setItem(OFFER_VARIANT_KEY, fromUrl); } catch (e) {}
      return fromUrl;
    }
    if (!IS_CHECKOUT_RETURN) { return ''; }
    try {
      var stored = sessionStorage.getItem(OFFER_VARIANT_KEY) || '';
      if (OFFER_VARIANT_RE.test(stored)) return stored;
    } catch (e) {}
    return '';
  }
  var OFFER_VARIANT = resolveOfferVariant();

  var ENTRY_SRC_KEY = 'gg_tp_entry_src';
  var ENTRY_SRC_RE = /^[a-z_]{1,24}$/;
  function resolveEntrySrc() {
    var fromUrl = '';
    try { fromUrl = new URLSearchParams(window.location.search).get('entry_src') || ''; } catch (e) {}
    if (ENTRY_SRC_RE.test(fromUrl)) {
      try { sessionStorage.setItem(ENTRY_SRC_KEY, fromUrl); } catch (e) {}
      return fromUrl;
    }
    if (!IS_CHECKOUT_RETURN) { return ''; }
    try {
      var stored = sessionStorage.getItem(ENTRY_SRC_KEY) || '';
      if (ENTRY_SRC_RE.test(stored)) return stored;
    } catch (e) {}
    return '';
  }
  var ENTRY_SRC = resolveEntrySrc();

  function track(event, params) {
    var payload = { entry_surface: ENTRY_SURFACE, form_version: FORM_VERSION };
    if (OFFER_VARIANT) { payload.offer_variant = OFFER_VARIANT; }
    if (ENTRY_SRC) { payload.entry_src = ENTRY_SRC; }
    if (params) { for (var k in params) payload[k] = params[k]; }
    if (typeof gtag === 'function') {
      gtag('event', event, payload);
    } else if (window.dataLayer) {
      var obj = { event: event };
      for (var k2 in payload) obj[k2] = payload[k2];
      window.dataLayer.push(obj);
    }
  }

  function analyticsConsentGranted() {
    if (/(^|; )gg_consent=declined/.test(document.cookie)) return false;
    if (/(^|; )gg_consent=accepted/.test(document.cookie)) return true;
    return window.ggConsentRequiresOptIn === false;
  }

  function findGaMeasurementId() {
    var configured = BRAND_CFG.gaMeasurementId || '';
    if (/^G-[A-Z0-9]+$/i.test(configured)) return configured;

    var scripts = document.querySelectorAll(
      'script[src*="googletagmanager.com/gtag/js"]'
    );
    for (var i = 0; i < scripts.length; i++) {
      try {
        var id = new URL(scripts[i].src, window.location.href).searchParams.get('id') || '';
        if (/^G-[A-Z0-9]+$/i.test(id)) return id;
      } catch (error) {
        // A malformed unrelated script URL must never block checkout.
      }
    }
    return '';
  }

  function readGtagValue(measurementId, field) {
    return new Promise(function(resolve) {
      var settled = false;
      var timer = setTimeout(function() {
        if (!settled) {
          settled = true;
          resolve('');
        }
      }, GA_ATTRIBUTION_TIMEOUT_MS);

      try {
        gtag('get', measurementId, field, function(value) {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve(String(value || ''));
        });
      } catch (error) {
        clearTimeout(timer);
        settled = true;
        resolve('');
      }
    });
  }

  function getGa4Attribution() {
    if (!analyticsConsentGranted() || typeof gtag !== 'function') {
      return Promise.resolve({});
    }
    var measurementId = findGaMeasurementId();
    if (!measurementId) return Promise.resolve({});

    return Promise.all([
      readGtagValue(measurementId, 'client_id'),
      readGtagValue(measurementId, 'session_id')
    ]).then(function(values) {
      var attribution = { analytics_consent: 'granted' };
      if (/^\d+\.\d+$/.test(values[0])) attribution.ga4_client_id = values[0];
      if (/^\d+$/.test(values[1])) attribution.ga4_session_id = values[1];
      return attribution;
    });
  }

  // ---- Helpers ----
  function daysUntil(raceDateStr) {
    var raceDate = new Date(raceDateStr + 'T00:00:00');
    var today = new Date();
    today.setHours(0, 0, 0, 0);
    return Math.round((raceDate - today) / (1000 * 60 * 60 * 24));
  }

  function dateState() {
    var v = raceDateInput.value;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return { ok: false, reason: 'missing' };
    var d = new Date(v + 'T00:00:00');
    if (isNaN(d.getTime())) return { ok: false, reason: 'missing' };
    var days = daysUntil(v);
    if (days < -PAST_GRACE_DAYS) return { ok: false, reason: 'past' };
    return { ok: true, days: days, pricing: computePrice(v) };
  }

  function raceLabel() {
    var n = (raceNameInput.value || '').trim();
    return n || 'Your race';
  }

  function validEmail(v) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v || '');
  }

  function showMessage(text) {
    messageEl.textContent = text;
    messageEl.style.display = 'block';
  }

  function hideMessage() {
    messageEl.style.display = 'none';
    messageEl.textContent = '';
  }

  // ---- Price line ----
  function updateQuote() {
    var st = dateState();
    if (!st.ok) {
      quoteEl.textContent = '';
      quoteEl.style.display = 'none';
      minNoteEl.style.display = 'none';
      if (termsPriceEl) termsPriceEl.textContent = TERMS_DEFAULT;
      if (st.reason === 'past' && raceDateInput.value) {
        quoteEl.textContent = 'That date has passed. Pick the race you are training for next.';
        quoteEl.style.display = 'block';
      }
      return st;
    }
    var rawWeeks = Math.ceil(st.days / 7);
    var out;
    if (rawWeeks < 1) out = raceLabel() + ' is less than a week out.';
    else if (rawWeeks === 1) out = raceLabel() + ' is 1 week out.';
    else out = raceLabel() + ' is ' + rawWeeks + ' weeks out.';
    quoteEl.textContent = out + ' Your plan: $' + st.pricing.price + ', paid once.';
    quoteEl.style.display = 'block';
    if (rawWeeks < MIN_WEEKS) {
      minNoteEl.textContent = 'A race less than ' + MIN_WEEKS + ' weeks out is priced as ' +
        MIN_WEEKS + ' weeks ($' + (MIN_WEEKS * PRICE_PER_WEEK) + ').';
      minNoteEl.style.display = 'block';
    } else {
      minNoteEl.style.display = 'none';
    }
    if (termsPriceEl) termsPriceEl.textContent = '$' + st.pricing.price;
    return st;
  }

  // ---- Persistence (a bounce back from Stripe keeps what was typed) ----
  function saveFields() {
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify({
        race_name: raceNameInput.value,
        race_date: raceDateInput.value,
        name: nameInput.value,
        email: emailInput.value,
        race_slug: prefilledRaceSlug || ''
      }));
    } catch (e) {}
  }

  function restoreFields() {
    try {
      var saved = JSON.parse(sessionStorage.getItem(STORAGE_KEY) || 'null');
      if (!saved) return;
      var urlRace = new URLSearchParams(window.location.search).get('race') || '';
      var sameRace = !urlRace || urlRace === saved.race_slug;
      if (sameRace) {
        if (saved.race_name && !raceNameInput.value) raceNameInput.value = saved.race_name;
        if (saved.race_date && !raceDateInput.value) raceDateInput.value = saved.race_date;
      }
      if (saved.name && !nameInput.value) nameInput.value = saved.name;
      if (saved.email && !emailInput.value) emailInput.value = saved.email;
    } catch (e) {}
  }

  // ---- Pre-populate the race from ?race=<slug> (same lookup as the full form) ----
  function prefillFromURL() {
    var params = new URLSearchParams(window.location.search);
    var raceSlug = params.get('race');
    if (!raceSlug) return;
    prefilledRaceSlug = raceSlug;

    // Humanize slug as fallback name: "unbound-200" → "Unbound 200"
    var fallbackName = raceSlug.replace(/-/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });

    fetch('/wp-content/uploads/race-index.json')
      .then(function(r) { return r.ok ? r.json() : Promise.reject(); })
      .then(function(races) {
        var match = races.find(function(r) { return r.slug === raceSlug; });
        prefilledRaceName = match ? match.name : fallbackName;
        if (!raceNameInput.value) raceNameInput.value = prefilledRaceName;
        updateQuote();
        track('tp_race_prefill', { race_slug: raceSlug, matched: !!match });
      })
      .catch(function() {
        prefilledRaceName = fallbackName;
        if (!raceNameInput.value) raceNameInput.value = fallbackName;
        updateQuote();
        track('tp_race_prefill', { race_slug: raceSlug, matched: false });
      });
  }

  // ---- Intent beacon (once, when name + email are valid) ----
  function sendIntentBeacon() {
    if (intentBeaconSent || formSubmitted) return;
    var nameVal = (nameInput.value || '').trim();
    var emailVal = (emailInput.value || '').trim();
    if (!nameVal || !validEmail(emailVal)) return;
    intentBeaconSent = true;
    var payload = JSON.stringify({
      name: nameVal,
      email: emailVal,
      sections_reached: 1,
      source: 'plan_start'
    });
    if (navigator.sendBeacon) {
      navigator.sendBeacon(API_BASE + '/questionnaire-started', new Blob([payload], {type: 'application/json'}));
    } else {
      fetch(API_BASE + '/questionnaire-started', {method: 'POST', body: payload, headers: {'Content-Type': 'application/json'}, keepalive: true}).catch(function() {});
    }
  }

  // ---- Wiring ----
  track('tp_step1_view', { has_race_param: !!new URLSearchParams(window.location.search).get('race') });
  restoreFields();
  prefillFromURL();
  updateQuote();

  form.addEventListener('focusin', function() {
    if (formStarted) return;
    formStarted = true;
    track('tp_form_start', { step: 1 });
  });
  form.addEventListener('input', function() {
    updateQuote();
    clearTimeout(form._saveTimeout);
    form._saveTimeout = setTimeout(saveFields, 500);
  });
  form.addEventListener('change', function() {
    updateQuote();
    saveFields();
  });
  nameInput.addEventListener('blur', sendIntentBeacon);
  emailInput.addEventListener('blur', sendIntentBeacon);
  emailInput.addEventListener('change', sendIntentBeacon);
  window.addEventListener('beforeunload', function() {
    if (formStarted && !formSubmitted) sendIntentBeacon();
  });

  // ---- Submit → Stripe Checkout ----
  form.addEventListener('submit', async function(e) {
    e.preventDefault();
    hideMessage();

    var raceName = (raceNameInput.value || '').trim();
    var nameVal = (nameInput.value || '').trim();
    var emailVal = (emailInput.value || '').trim();
    var st = updateQuote();

    var error = '';
    var errorCode = '';
    if (!raceName) { error = 'Which race is this plan for?'; errorCode = 'missing_race'; }
    else if (!st.ok && st.reason === 'past') { error = 'That race date has passed. Pick the race you are training for next.'; errorCode = 'past_date'; }
    else if (!st.ok) { error = 'Add your race date. The plan is built backward from it.'; errorCode = 'missing_date'; }
    else if (!nameVal) { error = 'Add your name.'; errorCode = 'missing_name'; }
    else if (!validEmail(emailVal)) { error = 'That email address doesn’t look right.'; errorCode = 'invalid_email'; }
    if (error) {
      showMessage(error);
      track('tp_form_error', { error: errorCode, step: 1 });
      return;
    }

    sendIntentBeacon();
    submitBtn.disabled = true;
    submitBtn.textContent = 'Preparing checkout...';

    var pricing = st.pricing;
    track('tp_step1_submit', { weeks: pricing.weeks, price: pricing.price });
    track('begin_checkout', {
      currency: 'USD',
      value: pricing.price,
      items: [{
        item_name: 'Custom Training Plan',
        item_category: 'training_plan',
        price: pricing.price
      }]
    });
    var ga4AttributionPromise = getGa4Attribution();

    var raceDate = raceDateInput.value;
    var payload = {
      intake_flow: 'two_step',
      name: nameVal,
      email: emailVal,
      races: [{ name: raceName, date: raceDate, distance: '', goal: '', priority: 'A' }],
      race_name: raceName,
      race_date: raceDate,
      website: honeypotInput ? honeypotInput.value : '',
      _source: FORM_SOURCE
    };
    // Carry the slug ONLY if the race is still the one we prefilled from
    // ?race= (the customer didn't swap it), same rule as the full form.
    if (prefilledRaceSlug && raceName === prefilledRaceName) {
      payload.race_slug = prefilledRaceSlug;
    }
    payload.entry_surface = ENTRY_SURFACE;
    if (OFFER_VARIANT) { payload.offer_variant = OFFER_VARIANT; }
    if (ENTRY_SRC) { payload.entry_src = ENTRY_SRC; }
    var ga4Attribution = await ga4AttributionPromise;
    payload.analytics_consent = ga4Attribution.analytics_consent || 'denied';
    if (ga4Attribution.ga4_client_id) {
      payload.ga4_client_id = ga4Attribution.ga4_client_id;
    }
    if (ga4Attribution.ga4_session_id) {
      payload.ga4_session_id = ga4Attribution.ga4_session_id;
    }

    try {
      var response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      var result = {};
      try { result = await response.json(); } catch (parseError) {}
      if (result.checkout_url) {
        formSubmitted = true;
        saveFields();
        // Marks the next pageload as a genuine return from Stripe, so the
        // stored attribution is still trusted — see IS_CHECKOUT_RETURN.
        try { sessionStorage.setItem(CHECKOUT_PENDING_KEY, '1'); } catch (e2) {}
        window.location.href = result.checkout_url;
        return;
      }
      throw new Error(result.error || 'Checkout didn’t open. Try again in a minute.');
    } catch (err) {
      showMessage(err.message || 'Something went wrong. Try again.');
      track('tp_form_error', { error: err.message || 'unknown', step: 1 });
      submitBtn.disabled = false;
      submitBtn.textContent = SUBMIT_LABEL;
      messageEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  });
})();
